package fr.arthurbrugiere.forgeline.core.ui.format

import androidx.compose.ui.graphics.Color

/**
 * The colours GitHub gives languages, from github-linguist 9.2.0 (MIT): every language Linguist colours, so a
 * repository's language bar has no grey gaps. The repository APIs name languages but don't give their colours;
 * a language Linguist doesn't colour gets none.
 */
fun languageColor(language: String?): Color? = language?.let { LANGUAGE_COLORS[it.lowercase()] }?.let { Color(0xFF000000 or it) }

